/// How far a local ref has diverged from the remote ref its push/pull actually acts on.
///
/// `comparedTo` is named in the short form the backend itself prints — git `origin/main`, jj
/// `main@origin` — because the toolbar tooltip quotes it verbatim (the `VCSPushScope.unpushedHelp`
/// pattern: name the ref, don't make the user guess what "behind" is behind).
///
/// Counts are always stated from the LOCAL ref's point of view: `ahead` = local commits the remote
/// doesn't have (what Push sends), `behind` = remote commits the local ref doesn't have (what Pull
/// brings). jj states its own counts from the REMOTE ref's point of view and they are therefore
/// swapped on the way in — see `VCSRemoteResolver.parseJJBookmarks`.
///
/// `nil` counts mean "unanswerable", never zero: an untracked jj remote bookmark, or a git ref whose
/// `%(push:track)`/`%(upstream:track)` field was empty *and* whose push ref didn't resolve. A missing
/// badge beats a wrong one (same rule as `VCSPushState.unknown`).
struct VCSTracking: Equatable, Sendable {
  let comparedTo: String
  let ahead: Int?
  let behind: Int?
  /// The tracking ref is configured but no longer exists on the remote — git `[gone]`, or a jj
  /// remote bookmark whose `.present()` is false. Counts are meaningless; the toolbar says
  /// "not on <remote> yet" and Push is the only sensible action.
  let gone: Bool
  /// The upstream a *pull* would rebase from, when it differs from `comparedTo` (a triangular
  /// `remote.pushDefault` setup, where `%(push)` and `%(upstream)` name different refs). `nil` ⇒
  /// they're the same ref, which is the case in every non-triangular repo.
  let pullFrom: String?

  var isInSync: Bool { !gone && ahead == 0 && behind == 0 }
  var isDiverged: Bool { (ahead ?? 0) > 0 && (behind ?? 0) > 0 }
}

/// One row of the branch/bookmark picker — a git branch (local or remote-tracking) or a jj bookmark.
/// `name` is the SHORT form git/jj print (`main`, `origin/main`, `workroom/foo`), never a `refs/…` path.
struct VCSBranchRef: Equatable, Identifiable, Sendable {
  enum Scope: Equatable, Sendable {
    /// git `refs/heads/*`, or a jj local bookmark.
    case local
    /// git `refs/remotes/<remote>/*`, or a jj `<name>@<remote>` with no local counterpart.
    /// Switching to one creates the local ref (`git switch --track` / `jj new <name>@<remote>`).
    case remote(String)
  }

  let name: String
  let scope: Scope
  /// Tip commit id. Empty ONLY for a jj remote bookmark deleted on the remote (`.present() == false`).
  let commitID: String
  /// Tip commit time, for recency ordering in the picker. `nil` when unreadable.
  let committedAt: Date?
  /// The ref the working copy is on right now (git `%(HEAD)` == `*`; the jj bookmark at `@`).
  let isCurrent: Bool
  /// The OTHER worktree/workspace that already has this ref checked out — git `%(worktreepath)`
  /// (nil'd when it equals this workroom's own path), jj the workspace name. Non-nil for git ⇒ a
  /// switch WILL fail (`'x' is already used by worktree at '…'`), so the picker must disable the row.
  /// For jj it's advisory only: jj happily lets two workspaces sit on the same bookmark.
  /// Always nil for a `.remote` ref.
  let checkedOutIn: String?
  /// This ref's own divergence from its own tracking ref, for a per-row `↑2 ↓1` hint. Free — it
  /// comes out of the same single command as the list.
  let tracking: VCSTracking?

  var id: String {
    switch scope {
    case .local: return "L:\(name)"
    case .remote(let remote): return "R:\(remote):\(name)"
    }
  }
}

/// When the repo last fetched. Three-way, not `Date?`, because the UI copy differs per case and the
/// app's rule is that "can't tell" must never render as "no" (cf. `VCSPushState`).
enum VCSLastFetch: Equatable, Sendable {
  case at(Date)
  /// No fetch has ever been recorded here: git has no `FETCH_HEAD` (a fresh `clone` or `init` never
  /// writes one), or jj's op log contains no fetch op within the scanned window.
  case never
  /// Unanswerable: the git dir couldn't be located, `FETCH_HEAD`'s attributes couldn't be read, the
  /// user has `fetch.writeFetchHEAD=false`, or the jj op-log read failed/timed out. The toolbar shows
  /// no timestamp at all rather than "never".
  case unknown
}

/// Everything the VCS inspector's toolbar renders, resolved as ONE coherent snapshot so the branch
/// name and the counts beside it can never come from two different reads of a moving repo.
struct VCSRemoteState: Equatable, Sendable {
  /// The current branch/bookmark, straight from `VCSProviding.currentRef` — the app's existing
  /// canonical answer, including `.ancestor` (jj `@` with no bookmark) and `.detached` (git).
  let current: VCSRef
  /// Divergence for `current`. `nil` ⇒ nothing to compare against (never pushed, detached HEAD,
  /// untracked bookmark) ⇒ no counts render.
  let tracking: VCSTracking?
  /// jj only: `@` sits ABOVE `current` with no bookmark of its own (`current.kind == .ancestor`), so
  /// `tracking` describes the ancestor bookmark's divergence and NOT your unbookmarked local work.
  /// The toolbar must say so rather than imply you're in sync. (The commit count is deferred — see
  /// the phase plan; a boolean is free and honest, a wrong number is neither.)
  let hasUnbookmarkedWork: Bool
  /// Picker rows, already ordered by `VCSRemoteResolver.pickerOrder`.
  let refs: [VCSBranchRef]
  /// Configured remote names, first-listed first. Empty ⇒ no remote ⇒ every network action is
  /// disabled. Derived from the ref list (git `refs/remotes/<remote>/*`, jj `<name>@<remote>`), so
  /// it costs no extra process.
  let remotes: [String]
  /// The remote the toolbar's Fetch/Push/Pull act on: `origin` when present, else the first remote,
  /// else `nil`. Origin-scoped by default, matching `GitGraph`/`VCSPushState`'s deliberate choice.
  let primaryRemote: String?
  let lastFetch: VCSLastFetch
  /// When this snapshot was read — the TTL key, and the `now` reference for the relative label.
  let resolvedAt: Date
  /// The ref list hit `VCSRemoteResolver.refCap`, so older refs are missing. The picker shows a
  /// "showing N most recent" footer instead of silently lying about the repo's branches.
  let refsTruncated: Bool
}
```

