    state: VCSRemoteState?, hasTarget: Bool, toolsUsable: Bool = true,
    activity: VCSSyncActivity = .idle, failure: VCSRemoteFailure? = nil,
    lastAction: VCSRemoteAction? = nil, pullRebase: Bool = true, now: Date
