func remoteTarget() -> RemoteStateModel.Target? {
  guard let sid = inspectorTargetID, let project = project(forSidebarID: sid) else { return nil }
  let path: String
  switch sid {
  case .root: path = project.path
  case .workroom(_, let name):
    guard let workroom = project.workrooms.first(where: { $0.name == name }) else { return nil }
    path = workroom.path
  }
  return RemoteStateModel.Target(
    sid: sid, path: path, vcs: project.vcs, projectRoot: project.path)
}

