/// Counts what the store asked of the model, without performing any VCS work.
private final class SpyRemoteModel: RemoteStateModel {
  private(set) var forcedRefreshes = 0
  private(set) var autoFetchChecks = 0
  private(set) var focuses: [Target?] = []

  init() {
    super.init(makeWriter: { _ in NoopWriter() }, debounce: 0)
  }

  func reset() {
    forcedRefreshes = 0
    autoFetchChecks = 0
    focuses = []
  }

  override func refresh(force: Bool = false) {
    if force { forcedRefreshes += 1 }
  }

  override func autoFetchIfDue() { autoFetchChecks += 1 }

  override func focus(_ target: Target?) { focuses.append(target) }
}

private struct NoopWriter: VCSWriting {
  func remoteState(path: String, projectRoot: String) async -> VCSRemoteResolution { .absent }
  func fetch(path: String, projectRoot: String, remote: String) async -> VCSRemoteActionResult {
    .ok(summary: "")
  }
  func push(
    path: String, projectRoot: String, current: VCSRef, remote: String, setUpstream: Bool,
    anonymousRevision: String
  ) async -> VCSRemoteActionResult { .ok(summary: "") }
  func pullRebase(
    path: String, projectRoot: String, current: VCSRef, remote: String, tracking: VCSTracking?
  ) async -> VCSRemoteActionResult { .ok(summary: "") }
  func abortRebase(path: String, projectRoot: String) async -> VCSRemoteActionResult {
    .ok(summary: "")
  }
}

