    sh("git init -q app", in: root)
    let project = root + "/app"
    sh("git commit -q --allow-empty -m initial", in: project)
    sh("git remote add origin ../origin.git", in: project)
    sh("git push -q -u origin HEAD:refs/heads/master", in: project)
