610	}
611	
612	/// The Changes section body: the selected workroom's branch, sync state, working-tree changes
613	/// (relative to HEAD), and CI. Reads `store.selectedTargetID` + `store.workroomStatuses`.
614	/// Covers the empty/edge states the design review enumerated: nothing selected, a project
615	/// (non-target), missing directory, still-loading, unknown (probe failed), and clean.
616	struct ChangesPanel: View {
617	  @EnvironmentObject var store: AppStore
618	  private let theme = ThemeService.shared
619	  /// Hard cap on rendered rows so a huge change set can't blow up the list (the underlying
620	  /// output is already byte-capped by `StatusCommandRunner`).
621	  private let renderCap = 200
622	
623	  var body: some View {
624	    Group {
625	      if let sid = store.inspectorTargetID, sid.isStatusable {
626	        content(for: sid)
627	      } else {
628	        inspectorMessage("Select a workroom to see its changes.")
629	      }
630	    }
631	    .frame(maxWidth: .infinity, alignment: .leading)
632	  }
633	
634	  @ViewBuilder
635	  private func content(for sid: SidebarID) -> some View {
636	    let target = store.target(for: sid)
637	    let status = store.workroomStatuses[sid]
638	    if let target, target.isMissing {
639	      inspectorMessage("Directory not found.")
640	    } else if status == nil || status?.lastChecked == nil {
641	      inspectorMessage("Checking\u{2026}")
642	    } else if let status {
643	      // Git and jj render the SAME shape: a branch/bookmark header over a flat change list. jj adds
644	      // the working copy's (`@`) change-id/commit-id/refs + description to the header, since `@` is
645	      // itself a commit. `jjWorkingCopy != nil` is the discriminator — a failed probe leaves it nil,
646	      // so failures fall to the git path (which renders the failure under a branch header, as before).
647	      let name = branchLabel(sid: sid, status: status)
648	      if let workingCopy = status.jjWorkingCopy {
649	        // A jj bookmark that names an ANCESTOR of `@` (rather than `@` itself) is a different thing
650	        // to the reader, and only the resolved `branchForCI` — not the `detached` fallback — can be
651	        // one, so the distinction is drawn here where the status is in hand.
652	        let ancestor =
653	          (status.branchForCI.map { !$0.isEmpty } ?? false) && !workingCopy.refs.contains(name)
654	        jjContent(name: name, workingCopy: workingCopy, ancestorBookmark: ancestor)
655	      } else {
656	        gitContent(name: name, status: status)
657	      }
658	    }
659	  }
660	
661	  /// Git repos: the branch header over the working-tree change list (or clean/failure). CI is
662	  /// GitHub-derived, so it lives in the Pull Request section — not here.
663	  @ViewBuilder
664	  private func gitContent(name: String, status: WorkroomStatus) -> some View {
665	    VStack(alignment: .leading, spacing: 10) {
666	      changesHeader(name: name, meta: nil, identifier: nil)
667	      Divider()
668	      if let failure = status.failure {
669	        inspectorMessage(failureText(failure))
670	      } else if status.isClean {
671	        cleanState
672	      } else {
673	        fileList(status.changedFiles ?? [], source: .gitWorktree)
674	      }
675	    }
676	    .padding(12)
677	  }
678	
679	  /// jj repos: the working copy (`@`) — its bookmark/branch name plus, because `@` is itself a
680	  /// commit, its change-id/commit-id/refs and description — over the flat change list, mirroring
681	  /// `gitContent`. The working copy's parent (`@-`) is no longer shown here; the History panel now
682	  /// surfaces it.
683	  @ViewBuilder
684	  private func jjContent(name: String, workingCopy: JJCommitChanges, ancestorBookmark: Bool)
685	    -> some View
686	  {
687	    VStack(alignment: .leading, spacing: 10) {
688	      changesHeader(
689	        name: name, meta: workingCopy, identifier: "changes.workingCopy",
690	        ancestorBookmark: ancestorBookmark)
691	      Divider()
692	      if workingCopy.files.isEmpty {
693	        cleanState
694	      } else {
695	        fileList(workingCopy.files, source: .jjWorkingCopy)
696	      }
697	    }
698	    .padding(12)
699	  }
700	
701	  /// The shared Changes header: the branch/bookmark name, plus (for jj, whose working copy is a
702	  /// commit) its change-id (purple) / commit-id (blue) / the refs the name pill doesn't already show,
703	  /// and the description line. `meta == nil` (git) renders just the name — git's working tree isn't a
704	  /// commit, so it carries no refs or message. `ancestorBookmark` says the name pill points at an
705	  /// ancestor of `@` rather than `@` itself, which only its tooltip distinguishes. `identifier`
706	  /// combines the header into one a11y element (jj only; the panel's render sentinel).
707	  @ViewBuilder
708	  private func changesHeader(
709	    name: String, meta: JJCommitChanges?, identifier: String?, ancestorBookmark: Bool = false
710	  ) -> some View {
711	    // jj's `branch_for_ci` (the left pill) is the first bookmark in `::@` log order, and `@` is the
712	    // first commit that walk emits — so whenever `@` itself is bookmarked, the left pill's name is
713	    // by construction also in `meta.refs`, and rendering both put ONE bookmark on screen as two
714	    // identical capsules. Chip only what the left pill isn't already showing. The case the left
715	    // pill exists for is untouched: when `@` carries no bookmark it names an ancestor's and `refs`
716	    // is empty. A multi-bookmark `@` still reads right — left pill = the alphabetically first,
717	    // chips = the rest.
718	    let extraRefs = (meta?.refs ?? []).filter { $0 != name }
719	    VStack(alignment: .leading, spacing: 2) {
720	      HStack(alignment: .firstTextBaseline, spacing: 6) {
721	        // The branch/bookmark the working copy is on, as the same gray pill the History list rows and
722	        // the changeset detail header give a ref — it names the same kind of thing, so it shouldn't
723	        // read as a bold title in one surface and a capsule in the others. Truncates in the MIDDLE
724	        // (unlike the ref pills beside it): a long branch name's distinguishing part is often its
725	        // tail (`joel/history-refs-pill`), so tail-truncating it would hide what tells it apart.
726	        Text(name).font(.caption)
727	          .lineLimit(1).truncationMode(.middle)
728	          .padding(.horizontal, 5).padding(.vertical, 1)
729	          .background(.quaternary, in: Capsule())
730	          // NOT "nearest": `branch_for_ci` is the first bookmark in `::@`'s LOG order, which at a
731	          // merge can be further away in the graph than one on another parent (see
732	          // `first_bookmark_in_log_order`'s doc). It is the first one walking down History, so that's
733	          // what the tooltip says.
734	          .help(ancestorBookmark ? "First ancestor bookmark in history" : "Bookmark / branch")
735	        if let meta {
736	          if let changeID = meta.changeID {
737	            Text(changeID).font(.system(.callout, design: .monospaced))
