import SwiftUI

/// Every number the VCS toolbar uses, in one place.
///
/// The horizontal ones are chosen so the toolbar aligns *by construction* with the section header
/// beneath it rather than by eye: `outerInset` + `glyphSlot` + `glyphSpacing` puts the branch glyph's
/// centre and the branch name's left edge exactly where `SectionHeader`'s chevron centre and title land
/// (`InspectorSplitView.headerLabel` uses the same 12 / 12 / 7).
enum VCSToolbarMetrics {
  /// 11pt semibold title (13pt line) + 1pt + 10pt caption (12pt line) = 26, plus 5pt above and below.
  /// Two lines genuinely don't fit the section headers' 34pt, and 36 also reads as a distinct band.
  static let height: CGFloat = 36
  static let outerInset: CGFloat = 12
  /// Inner edges of the segments — tighter than `outerInset` so the middle segment isn't starved.
  static let innerInset: CGFloat = 8
  /// Matches `SectionHeader`'s chevron `.frame(width: 12)`.
  static let glyphSlot: CGFloat = 12
  /// Matches `SectionHeader`'s `HStack(spacing: 7)`.
  static let glyphSpacing: CGFloat = 7
  /// Between the inspector's 11pt header glyphs and the pane bar's 13pt action icons: it has to hold
  /// against a bold 11pt title without reading as a pane-bar button.
  static let glyph: CGFloat = 12
  /// 22pt well plus 4pt either side — `ToolbarIconButtonStyle.footprint` rounded to a divider-bounded cell.
  static let fetchWidth: CGFloat = 30

  static let titleFont = Font.system(size: 11, weight: .semibold)
  static let captionFont = Font.system(size: 10)
  /// The single-line states. A lone 10pt dim line in a 36pt bar reads as a rendering bug, so the solo
  /// subtitle is a step up in both size and contrast.
  static let soloFont = Font.system(size: 11)

  /// Floors, chosen so the inspector's 260pt minimum fits with room to spare:
  /// `branchMin + syncMin + fetchWidth + 2 dividers = 258`.
  static let branchMinWidth: CGFloat = 100
  /// Caps the branch cell so a short name can't hoard space the sync segment can use.
  static let branchMaxWidth: CGFloat = 220
  static let syncMinWidth: CGFloat = 126
  /// Below this the "Current Branch" caption drops — the icon already says "branch", and it's the least
  /// useful pixel in the bar.
  static let branchCaptionThreshold: CGFloat = 120

  /// Verbatim from `PRNumberBadge`, so the toolbar's pill matches the ref pill 40pt below it.
  static let pillHorizontalPadding: CGFloat = 5
  static let pillVerticalPadding: CGFloat = 1
}

/// The VCS toolbar: current branch, a sync segment that shows and performs the right remote action, and
/// a fetch button — divided into three full-height cells.
///
/// Lives at the top of `RightInspector`, above the section stack, and only for the Changes activity

import XCTest

@testable import Workroom

/// `VCSToolbarMetrics` — the toolbar's geometry, asserted rather than eyeballed.
///
/// Two properties matter and neither is visible in a screenshot: the segments must FIT the inspector's
/// 260pt minimum (below that something clips, and the clipping is what a user sees, not the cause), and
/// the toolbar must align with the section header beneath it by construction rather than by luck.
final class VCSToolbarMetricsTests: XCTestCase {

  /// The inspector's minimum content width. `InspectorColumn` clamps to 260-520 and applies the width to
  /// `RightInspector` before the card's padding, so the toolbar gets exactly this.
  private let inspectorMinWidth: CGFloat = 260

  /// The floors plus both dividers must fit the narrowest inspector. If a future tweak pushes this over,
  /// the toolbar clips at the minimum width — which is the default for anyone who has never dragged the
  /// divider.
  func testSegmentFloorsFitTheNarrowestInspector() {
    let required =
      VCSToolbarMetrics.branchMinWidth + VCSToolbarMetrics.syncMinWidth
      + VCSToolbarMetrics.fetchWidth + 2  // one 1pt divider between each pair
    XCTAssertLessThanOrEqual(
      required, inspectorMinWidth,
      "the three segments need \(required)pt but the inspector can be \(inspectorMinWidth)pt wide")
  }

  /// The toolbar's leading geometry is deliberately identical to `SectionHeader.headerLabel`'s, so the
  /// branch glyph's centre and the branch name's left edge line up with the Changes header's chevron
  /// centre and title. Alignment by construction; this is the assertion that keeps it that way.
  func testLeadingGeometryMatchesTheSectionHeader() {
    // SectionHeader: .padding(.horizontal, 12), chevron .frame(width: 12), HStack(spacing: 7).
    let headerInset: CGFloat = 12
    let headerGlyphSlot: CGFloat = 12
    let headerSpacing: CGFloat = 7

    XCTAssertEqual(VCSToolbarMetrics.outerInset, headerInset)
    XCTAssertEqual(VCSToolbarMetrics.glyphSlot, headerGlyphSlot)
    XCTAssertEqual(VCSToolbarMetrics.glyphSpacing, headerSpacing)

    let glyphCentre = VCSToolbarMetrics.outerInset + VCSToolbarMetrics.glyphSlot / 2
    let textLeadingEdge =
      VCSToolbarMetrics.outerInset + VCSToolbarMetrics.glyphSlot + VCSToolbarMetrics.glyphSpacing
    XCTAssertEqual(glyphCentre, 18, "glyph centre must sit where the header's chevron centre does")
    XCTAssertEqual(textLeadingEdge, 31, "text must start where the header's title does")
  }

  /// 11pt semibold (13pt line) + 1pt + 10pt (12pt line) = 26, plus 5pt above and below. The section
  /// headers are 34pt, which two lines don't fit — so this must be taller than them, not equal.
  func testHeightFitsTwoLinesAndExceedsASectionHeader() {
    XCTAssertGreaterThan(
      VCSToolbarMetrics.height, InspectorPanePolicy.headerHeight,
      "two stacked lines don't fit a section header's height")
    XCTAssertEqual(VCSToolbarMetrics.height, 36)
  }

  /// The fetch cell has to hold a standard 22pt hover well.
  func testFetchCellFitsAStandardWell() {
    XCTAssertGreaterThanOrEqual(
      VCSToolbarMetrics.fetchWidth, ToolbarIconButtonStyle.wellSize,
      "the fetch glyph's well would overflow its cell")
  }

  /// A cap, not a floor — without it a short branch name hoards width the sync segment could use for the
  /// full "Fetched N minutes ago".
  func testBranchSegmentIsCapped() {
    XCTAssertGreaterThan(VCSToolbarMetrics.branchMaxWidth, VCSToolbarMetrics.branchMinWidth)
    XCTAssertLessThan(
      VCSToolbarMetrics.branchMaxWidth, inspectorMinWidth,
      "the branch cell must never be able to take the whole bar")
  }

  /// The caption drops before the name does: the icon already says "branch", so the label is the least
  /// useful pixel in the cell.
  func testCaptionDropsWhileTheBranchCellIsStillAboveItsFloor() {
    XCTAssertGreaterThan(
      VCSToolbarMetrics.branchCaptionThreshold, VCSToolbarMetrics.branchMinWidth,
      "the caption must drop before the cell is squeezed to its floor, not after")
  }

  /// Pill geometry is copied from `PRNumberBadge` so the toolbar's count pill matches the ref pill in the
  /// Changes header ~40pt below it. Two pills that nearly match read worse than two that differ clearly.
  func testPillGeometryMatchesThePRBadge() {
    XCTAssertEqual(VCSToolbarMetrics.pillHorizontalPadding, 5)
    XCTAssertEqual(VCSToolbarMetrics.pillVerticalPadding, 1)
  }
}

