/// jj calls them bookmarks, and the distinction is real rather than cosmetic — a jj bookmark doesn't
/// move as you commit, which is the opposite of a git branch's defining behaviour. Naming it "Branch"
/// in a jj repo would teach the wrong model of the tool the user is actually running.
private var branchCaption: String {
  model.target?.vcs == "jj" ? "Current Bookmark" : "Current Branch"
}

