  /// commit, which is a git branch's defining property — so the wrong word teaches the wrong model.
  ///
  /// Needs `-WorkroomUITestJJProject 1`: the fixture otherwise declares its project `git` while feeding
  /// jj-shaped status, which is exactly how this shipped saying "Current Branch" over jj data with nothing
  /// able to catch it. `VCSSyncPresentationTests` pins the mapping; only this tier proves the caption
  /// actually renders the jj word for a jj project.
  func testJJProjectSaysBookmarkNotBranch() {
    let app = launchedApp(
      syncState: "ahead", extraArguments: ["-WorkroomUITestJJProject", "1"])
    XCTAssertTrue(waitExists(branch(app)))
    XCTAssertTrue(
      waitLabel(branch(app), contains: "Bookmark"),
      "a jj project's caption must read Current Bookmark; got \(branch(app).label)")
    XCTAssertFalse(
      branch(app).label.contains("Branch"), "and must not also say Branch")
    XCTAssertEqual(
      branch(app).value as? String, "feature/login",
      "the name itself is unchanged — only the noun differs")
  }

  /// The caption is not optional. It used to sit in a `ViewThatFits` ladder against a name-only variant,
  /// and because `ViewThatFits` measures each variant's IDEAL width — a truncating `Text` reports its full
  /// untruncated string — a long NAME vetoed the caption even in a wide inspector. jj projects lost it
  /// almost always while git kept it, which is how the asymmetry got reported.
  func testCaptionRendersRegardlessOfNameLength() {
    let app = launchedApp(syncState: "ahead", extraArguments: ["-WorkroomUITestLongWorkroomName", "1"])
    XCTAssertTrue(waitExists(branch(app)))
    XCTAssertTrue(
      waitLabel(branch(app), contains: "Current"),
      "the caption must survive a long name rather than being silently dropped; got "
        + branch(app).label)
  }

  // MARK: The button → engine seam

  /// Clicking the sync segment must actually request the action it names. `-WorkroomUITestSyncFailure`
  /// makes the requested action observable: the failure tier renders the failed action's own label.
  func testClickingPushRequestsAPush() {
    let app = launchedApp(syncState: "ahead", extraArguments: ["-WorkroomUITestSyncFailure", "1"])
    XCTAssertTrue(waitExists(sync(app)))
    XCTAssertTrue(waitLabel(sync(app), contains: "Push"))
    XCTAssertTrue(button(app, id: "vcs.toolbar.sync").isHittable)
    button(app, id: "vcs.toolbar.sync").click()
    XCTAssertTrue(
      waitLabel(sync(app), contains: "authenticate", 10),
      "a failed push must surface inline on the segment; got \(sync(app).label)")
  }

  /// The fixture delays each action, so the in-flight state is observable — and while it's in flight the
  /// segment must be disabled, which is what stops a double-click firing twice.
  func testInFlightActionDisablesTheSegment() {
    let app = launchedApp(syncState: "ahead")
    XCTAssertTrue(waitExists(sync(app)))
    XCTAssertTrue(waitLabel(sync(app), contains: "Push"))
    XCTAssertTrue(button(app, id: "vcs.toolbar.sync").isHittable)
    button(app, id: "vcs.toolbar.sync").click()
    XCTAssertTrue(
      waitLabel(sync(app), contains: "Pushing", 6),
      "the in-flight state should render; got \(sync(app).label)")
    XCTAssertFalse(sync(app).isEnabled, "a second click must not be able to fire another push")
  }

  func testClickingFetchRunsAFetch() {
    let app = launchedApp(syncState: "clean")
    XCTAssertTrue(waitExists(fetch(app)))
    XCTAssertTrue(fetch(app).isEnabled)
    XCTAssertTrue(button(app, id: "vcs.toolbar.fetch").isHittable)
    button(app, id: "vcs.toolbar.fetch").click()
    XCTAssertTrue(
      waitLabel(sync(app), contains: "Fetching", 6),
      "the sync segment reports the in-flight fetch; got \(sync(app).label)")
  }

  /// A failed action must NOT blank the toolbar — the branch is still known, and the repo is unchanged.
  func testAFailedActionKeepsTheBranchVisible() {
    let app = launchedApp(syncState: "ahead", extraArguments: ["-WorkroomUITestSyncFailure", "1"])
    XCTAssertTrue(waitExists(sync(app)))
    XCTAssertTrue(button(app, id: "vcs.toolbar.sync").isHittable)
    button(app, id: "vcs.toolbar.sync").click()
    XCTAssertTrue(waitLabel(sync(app), contains: "authenticate", 10))
    XCTAssertEqual(
      branch(app).value as? String, "feature/login",
      "a failed action tells you nothing new about the repo, so the snapshot must stand")
  }
}

