184	  static func merging(_ state: VCSRemoteState, ownFetch: Date?) -> VCSRemoteState {
185	    guard let ownFetch else { return state }
186	    let merged: VCSLastFetch
187	    switch state.lastFetch {
188	    case .at(let backend): merged = .at(max(backend, ownFetch))
189	    case .never, .unknown: merged = .at(ownFetch)
190	    }
191	    return VCSRemoteState(
192	      current: state.current, tracking: state.tracking, remotes: state.remotes,
193	      primaryRemote: state.primaryRemote, lastFetch: merged, resolvedAt: state.resolvedAt)
