  XCTAssertEqual(
    CLIVCSWriter.opDirectory(.push, path: "/w/room", projectRoot: "/p"), "/w/room")
  XCTAssertEqual(
    CLIVCSWriter.opDirectory(.push, path: "/w/room", projectRoot: "/p"), "/p")
}

func testPullAndAbortRunInTheWorkroom() {
  for vcs in ["git", "jj"] {
